"""C1 nose between overlapping original corner circles, evaluated natively.

The original corner radii, centers and source contacts stay fixed. A separate
Join Radius describes the new third arc; invalid or ambiguous constructions
are rejected, never repaired by shrinking a specified radius. The caller must
still certify the complete boundary, footprint, profiles and surface mesh.
"""
import math
import bpy
from . import curved_corner_nodes as c

NAME = 'Prochitecture Streets / Retained corner circles compound nose v1'


def arc_fields(g,corners,at):
    """Ordered original/join/original arcs for a compound boundary side.

    The corner table comes from the native compound boundary, not Python-solved
    coordinates. Ordinary sides retain their single original arc.
    """
    read=lambda key,kind='FLOAT':c._read(g,corners,key,at,kind)
    active=read('st_cp_compound','BOOLEAN')
    centers=[read(key,'FLOAT_VECTOR') for key in ('st_cc_center','st_cp_join_center','st_cp_second_center')]
    starts=[read(key,'FLOAT_VECTOR') for key in ('st_cc_contact_a','st_cp_join_a','st_cp_join_b')]
    radii=[read(key) for key in ('st_cc_radius','st_cp_join_radius','st_cp_second_radius')]
    sweeps=[c.choose(g,active,read('st_cp_sweep_a'),read('st_cc_sweep')),
            c.choose(g,active,read('st_cp_sweep_join'),0.),c.choose(g,active,read('st_cp_sweep_b'),0.)]
    lengths=[r*g.math('ABSOLUTE',s) for r,s in zip(radii,sweeps)]
    return active,centers,starts,radii,sweeps,lengths


def arc_jet(g,corners,at,fraction,total_rate):
    """Position and one-sided derivative of all arcs using total arc length."""
    active,centers,starts,radii,sweeps,lengths=arc_fields(g,corners,at)
    distance=fraction*sum(lengths);point=[0.,0.];derivative=[0.,0.];turn=0.
    base=0.
    for n,(center,start,radius,sweep,length) in enumerate(zip(centers,starts,radii,sweeps,lengths)):
        q=c.bounded(g,(distance-base)/g.math('MAXIMUM',length,1e-12))
        delta=c._sub(c._vec(g,start),c._vec(g,center));angle=g.math('ARCTAN2',delta[1],delta[0])+q*sweep
        rate=sweep*total_rate/g.math('MAXIMUM',length,1e-12)
        xy=c._add(c._vec(g,center),c._scale([g.math('COSINE',angle),g.math('SINE',angle)],radius))
        d=c._scale([-g.math('SINE',angle),g.math('COSINE',angle)],radius*rate)
        use=True if n==0 else active*g.math('GREATER_THAN',distance,base)
        point=c._pick(g,use,xy,point);derivative=c._pick(g,use,d,derivative);turn=c.choose(g,use,rate,turn)
        base=base+length
    return point,derivative,turn


def _sweep(g, first, last):
    angle = g.math('ARCTAN2', c._cross(first,last), c._dot(first,last))
    return c.choose(g,g.math('GREATER_THAN',angle,0.),angle-math.tau,angle)


def build():
    if NAME in bpy.data.node_groups:return bpy.data.node_groups[NAME]
    g=c.Graph(NAME)
    for side in ('A','B'):
        for key in ('Center','Contact'):g.socket(key+' '+side,'NodeSocketVector')
        g.socket('Radius '+side,'NodeSocketFloat',default=2.)
        g.socket('Original Sweep '+side,'NodeSocketFloat',default=-math.pi/2.)
    g.socket('Join Radius','NodeSocketFloat',default=1.)
    g.socket('Input Valid','NodeSocketBool',default=False)
    for key in ('Join Center','Join A','Join B'):g.socket(key,'NodeSocketVector','OUTPUT')
    for key in ('Sweep A','Sweep Join','Sweep B'):g.socket(key,'NodeSocketFloat','OUTPUT')
    g.socket('Candidate Count','NodeSocketInt','OUTPUT');g.socket('Valid','NodeSocketBool','OUTPUT')
    inp=g.node('NodeGroupInput');out=g.node('NodeGroupOutput')
    ca,cb,pa,pb=[c._vec(g,inp.outputs[key]) for key in ('Center A','Center B','Contact A','Contact B')]
    ra,rb,rn=[c.V(g,inp.outputs[key]) for key in ('Radius A','Radius B','Join Radius')]
    wa,wb=[c.V(g,inp.outputs['Original Sweep '+side]) for side in ('A','B')]
    delta=c._sub(cb,ca);d=c._length(g,delta);aa,bb=ra-rn,rb-rn
    axis=c._scale(delta,g.math('DIVIDE',1.,g.math('MAXIMUM',d,1e-12)))
    normal=c._scale(c._right(axis),-1.)
    x=(aa*aa-bb*bb+d*d)/g.math('MAXIMUM',2.*d,1e-12)
    h=g.math('SQRT',g.math('MAXIMUM',0.,aa*aa-x*x))
    valid=c.V(g,inp.outputs['Input Valid'])*g.math('GREATER_THAN',rn,1e-6)
    valid=valid*g.math('GREATER_THAN',g.math('MINIMUM',aa,bb),1e-6)
    valid=valid*g.math('GREATER_THAN',d,g.math('ABSOLUTE',aa-bb)+1e-6)
    valid=valid*g.math('LESS_THAN',d,aa+bb-1e-6)
    # Bounded finite comparisons also reject infinities and NaN inputs.
    for radius in (ra,rb,rn):valid=valid*g.math('LESS_THAN',radius,1e5)
    for point in (ca,cb,pa,pb):
        valid=valid*g.math('LESS_THAN',c._length(g,point),1e6)
    for key in ('Center A','Center B','Contact A','Contact B'):
        valid=valid*g.math('LESS_THAN',g.math('ABSOLUTE',g.separate(inp.outputs[key])[2]),1e-6)
    for point,center,radius,sweep in ((pa,ca,ra,wa),(pb,cb,rb,wb)):
        error=g.math('ABSOLUTE',c._length(g,c._sub(point,center))-radius)
        valid=valid*g.math('LESS_THAN',error,2e-5)
        valid=valid*g.math('LESS_THAN',sweep,-1e-7)*g.math('GREATER_THAN',sweep,-math.pi-1e-6)
    candidates=[]
    for sign in (-1.,1.):
        center=c._add(ca,c._add(c._scale(axis,x),c._scale(normal,sign*h)))
        ja=c._add(ca,c._scale(c._sub(center,ca),ra/g.math('MAXIMUM',aa,1e-12)))
        jb=c._add(cb,c._scale(c._sub(center,cb),rb/g.math('MAXIMUM',bb,1e-12)))
        sweeps=[_sweep(g,c._sub(start,origin),c._sub(end,origin)) for start,end,origin in
                ((pa,ja,ca),(ja,jb,center),(jb,pb,cb))]
        ok=valid
        for sweep in sweeps:
            ok=ok*g.math('LESS_THAN',sweep,-1e-7)*g.math('GREATER_THAN',sweep,-math.pi-1e-6)
        ok=ok*g.math('GREATER_THAN',sweeps[0],wa-1e-6)*g.math('GREATER_THAN',sweeps[2],wb-1e-6)
        candidates.append((ok,[center,ja,jb],sweeps))
    count=candidates[0][0]+candidates[1][0]
    unique=g.math('COMPARE',count,1.)
    # Outputs are meaningful only when Valid is true. Invalid coordinates are
    # zeroed so downstream inspection cannot mistake a rejected branch for one.
    for at,key in enumerate(('Join Center','Join A','Join B')):
        value=c._pick(g,candidates[0][0],candidates[0][1][at],candidates[1][1][at])
        g.bind(g.xyz(*c._pick(g,unique,value,[0.,0.])),out.inputs[key])
    for at,key in enumerate(('Sweep A','Sweep Join','Sweep B')):
        value=c.choose(g,candidates[0][0],candidates[0][2][at],candidates[1][2][at])
        g.bind(c.choose(g,unique,value,0.),out.inputs[key])
    g.bind(count,out.inputs['Candidate Count']);g.bind(unique,out.inputs['Valid'])
    return g.g
